from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Naive SYR2K kernel: direct translation of the PolyBench reference.
@proc
def syr2k_base(
    n: size,
    m: size,
    alpha: DATA_TYPE,
    beta: DATA_TYPE,
    C: DATA_TYPE[n, n] @ DRAM,
    A: DATA_TYPE[n, m] @ DRAM,
    B: DATA_TYPE[n, m] @ DRAM,
):
    # Scale the lower triangle of C (including the diagonal) by beta.
    for i in seq(0, n):
        for j in seq(0, i + 1):
            C[i, j] = beta * C[i, j]

        # Rank-2k symmetric update of the same lower triangle:
        #   C[i,j] += A[j,k] * alpha * B[i,k] + B[j,k] * alpha * A[i,k]
        # This matches the original driver’s computation.
        for k in seq(0, m):
            for j in seq(0, i + 1):
                C[i, j] += (
                    A[j, k] * alpha * B[i, k]
                    + B[j, k] * alpha * A[i, k]
                )


# ---------------------------------------------------------------------------
# Optimization schedule
# ---------------------------------------------------------------------------
# We now transform 'syr2k_base' into an optimized kernel using Exo's
# scheduling primitives. The final exported procedure is named 'kernel_syr2k'.
# All transformations are semantics-preserving but improve locality and
# parallelism:
#   - Reorder loops to make accesses to A and B contiguous.
#   - Fuse j-loops so that each C[i,j] element is scaled then updated.
#   - Tile the reduction dimension k to improve cache reuse.
#   - Parallelize the outer i-loop across cores (OpenMP in the backend).
# ---------------------------------------------------------------------------

syr2k_opt = syr2k_base

# 1) Improve data locality for A and B by iterating over k inside j.
#    Original structure (for each i):
#       for k in 0..m-1:
#         for j in 0..i:
#           C[i,j] += f(i,j,k)
#    After reordering we get:
#       for j in 0..i:
#         for k in 0..m-1:
#           C[i,j] += f(i,j,k)
#    This keeps A[j,k] and B[j,k] as row-contiguous accesses.
syr2k_opt = reorder_loops(syr2k_opt, "k j")

# 2) Fuse the two j-loops inside each i-iteration:
#       for j: C[i,j] = beta * C[i,j]
#       for j: for k: C[i,j] += ...
#    becomes:
#       for j:
#         C[i,j] = beta * C[i,j]
#         for k: C[i,j] += ...
#    This ensures each C[i,j] is scaled once and then immediately updated,
#    improving temporal locality for C.
syr2k_opt = fuse(
    syr2k_opt,
    "for j in _:_ #0",  # first j-loop (scaling)
    "for j in _:_ #1",  # second j-loop (update)
)

